84	if (process.env.ANTHROPIC_API_KEY) delete process.env.ANTHROPIC_API_KEY;
85	
86	function assertSdkCredentials(): void {
87	  // Two valid ways to authenticate, and a dev machine usually uses the second:
88	  //   1. CLAUDE_CODE_OAUTH_TOKEN — headless servers (the VM).
89	  //   2. ~/.claude/.credentials.json — written by an interactive
90	  //      `claude setup-token` login, which is what a workstation already has.
91	  // Requiring (1) unconditionally broke local development, where (2) is
92	  // present and perfectly sufficient.
93	  const home = process.env.HOME ?? process.env.USERPROFILE;
94	  const hasCredentialsFile =
95	    !!home && existsSync(path.join(home, ".claude", ".credentials.json"));
96	
97	  if (!process.env.CLAUDE_CODE_OAUTH_TOKEN && !hasCredentialsFile) {
98	    throw new Error(
99	      "KODELY_ENGINE=sdk but no subscription credentials were found. " +
100	        "Either run `claude setup-token` as this user, or set " +
101	        "CLAUDE_CODE_OAUTH_TOKEN in the environment.",
102	    );
103	  }
104	}
105	
106	/**
107	 * Map a raw model id from the SDK onto a key in MODEL_RATES.
108	 *
109	 * The SDK reports concrete ids ("claude-sonnet-5-20250929"), while the rate
110	 * card is keyed by family. Anything unrecognised is returned unchanged so
111	 * costMicros() falls through to its deliberately conservative `default` rate
112	 * — an unknown model should over-estimate, never under-bill.
113	 */
114	function toRateKey(model: string): string {
115	  const m = model.toLowerCase();
116	  if (m.includes("opus")) return "claude-opus-5";
117	  if (m.includes("sonnet")) return "claude-sonnet-5";
118	  if (m.includes("haiku")) return "claude-haiku-4-5";
119	  return model;
120	}
121	
122	/**
123	 * Turn an SDK result into the usage event the charging path expects.
124	 *
125	 * IMPORTANT — what this cost means. On the subscription there is no metered
126	 * per-build charge, so this is an IMPUTED cost: the real tokens this build
127	 * consumed, priced at the API rate card. It is what the build WOULD have cost
128	 * on metered billing, not money that left an account.
129	 *
130	 * That is deliberately more useful than reporting zeros. Zeroed usage made
131	 * every SDK build cost exactly 1 credit (the floor) and flatlined the
132	 * cost/margin dashboard — which is the instrument for the board's "riskiest
133	 * assumption #1", whether infra can beat credit economics. With real token
134	 * counts the credit meter, the ledger and the margin view all behave exactly
135	 * as they will on metered billing, which is what makes them testable now.
136	 *
137	 * `modelUsage` is the field the SDK documents as correct for token accounting:
138	 * it spans the main loop plus subagents and internal calls, where `usage`
139	 * covers only the main loop. It is cumulative per query() call, so it is read
140	 * once from the final result rather than summed across results.
141	 */
142	function meterUsage(message: { modelUsage?: Record<string, ModelUsage> }): {
143	  model: string;
144	  inputTokens: number;
145	  outputTokens: number;
146	  cacheReadTokens: number;
147	  cacheWriteTokens: number;
148	} {
149	  const usage = message.modelUsage ?? {};
150	  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
151	
152	  // The charging path takes ONE model string plus summed tokens, so attribute
153	  // the build to whichever model produced the most output tokens — output
154	  // dominates cost on every rate in the card. In practice Claude Code runs one
155	  // model for the main loop, so this is usually exact; when a cheap auxiliary
156	  // model also ran, its tokens are still counted, just priced at the main
157	  // model's rate. That errs toward over-billing, never under.
158	  let dominant = "";
159	  let mostOutput = -1;
160	
161	  for (const [model, u] of Object.entries(usage)) {
162	    totals.inputTokens += u.inputTokens ?? 0;
163	    totals.outputTokens += u.outputTokens ?? 0;
164	    totals.cacheReadTokens += u.cacheReadInputTokens ?? 0;
165	    totals.cacheWriteTokens += u.cacheCreationInputTokens ?? 0;
166	    if ((u.outputTokens ?? 0) > mostOutput) {
167	      mostOutput = u.outputTokens ?? 0;
168	      dominant = u.canonicalModel ?? model;
169	    }
170	  }
171	
172	  return {
173	    // No usage at all (a crashed or startup-error result) keeps the old
174	    // self-explaining tag, so a 1-credit build is visibly "no telemetry"
175	    // rather than looking like a genuinely free one.
176	    model: dominant ? toRateKey(dominant) : "claude-agent-sdk-subscription",
177	    ...totals,
178	  };
179	}
