181	/** Reject path traversal and absolute paths before anything touches the DB. */
182	function safeRelPath(raw: string): string | null {
183	  const p = raw.trim().replace(/^\.?\//, "");
184	  if (!p || p.length > 200) return null;
185	  if (p.includes("..") || p.startsWith("/") || p.includes("\\")) return null;
186	  if (!/^[A-Za-z0-9._/-]+$/.test(p)) return null;
187	  return p;
188	}
