190	async function writeFileMap(dir: string, files: FileMap) {
191	  for (const [rel, content] of Object.entries(files)) {
192	    const full = path.join(dir, rel);
193	    await mkdir(path.dirname(full), { recursive: true });
194	    await writeFile(full, content, "utf8");
195	  }
196	}
