198	async function readFileTree(dir: string, prefix = ""): Promise<FileMap> {
199	  const { readdir } = await import("node:fs/promises");
200	  const out: FileMap = {};
201	  const entries = await readdir(dir, { withFileTypes: true });
202	  for (const e of entries) {
203	    if (e.name === "node_modules" || e.name === ".git" || e.name.startsWith(".")) continue;
204	    const rel = prefix ? `${prefix}/${e.name}` : e.name;
205	    const full = path.join(dir, e.name);
206	    if (e.isDirectory()) Object.assign(out, await readFileTree(full, rel));
207	    else out[rel] = await readFile(full, "utf8");
208	  }
209	  return out;
210	}
211	
212	type SdkOptions = {
213	  history: { role: "user" | "assistant"; content: string }[];
214	  request: string;
215	  files: FileMap;
216	  kind: "create" | "edit";
217	  image?: { mediaType: string; data: string };
218	  onWrite: (path: string, content: string) => Promise<boolean>;
219	  onDelete: (path: string) => Promise<boolean>;
220	  signal?: AbortSignal;
221	};
222	
223	export async function* runAgentSdk(
224	  opts: SdkOptions,
225	  systemPrompt: string,
226	): AsyncGenerator<AgentEvent> {
227	  // The SDK edits a real directory rather than calling tools over the wire,
228	  // so the project is materialised to a temp dir and diffed afterwards.
229	  assertSdkCredentials();
230	  const workDir = await mkdtemp(path.join(tmpdir(), "kodely-sdk-"));
231	
232	  try {
233	    await writeFileMap(workDir, opts.files);
234	
235	    let imageNote = "";
236	    if (opts.image) {
237	      const ext = opts.image.mediaType.split("/")[1] ?? "png";
238	      await writeFile(path.join(workDir, `.reference.${ext}`), Buffer.from(opts.image.data, "base64"));
239	      imageNote = `\n\nA reference image was attached to this request — Read the file .reference.${ext} in this directory to see it, then use it as visual/style guidance.`;
240	    }
241	
242	    const historyText = opts.history.length
243	      ? `## Prior conversation on this project\n${opts.history
244	          .map((h) => `${h.role === "user" ? "User" : "You"}: ${h.content}`)
245	          .join("\n\n")}\n\n`
246	      : "";
247	
248	    yield {
249	      type: "status",
250	      text: opts.kind === "create" ? "Building your site…" : "Applying your changes…",
251	    };
252	
253	    for await (const message of query({
254	      prompt: `${historyText}## Current request\n${opts.request}${imageNote}`,
255	      options: {
256	        cwd: workDir,
257	        systemPrompt: adaptPromptForSdk(systemPrompt),
258	        allowedTools: ["Read", "Write", "Edit", "Bash", "Glob", "Grep"],
259	        permissionMode: "acceptEdits",
260	      },
261	    })) {
262	      if (opts.signal?.aborted) break;
263	
264	      if (message.type === "assistant" && message.message?.content) {
265	        for (const block of message.message.content) {
266	          if ("text" in block && block.text) {
267	            yield { type: "text", text: block.text };
268	          } else if (block.type === "tool_use") {
269	            // The only live signal this engine gives. Files are diffed out of
270	            // the working directory AFTER query() finishes, so without this the
271	            // chat sits silent for the whole build and then dumps every file at
272	            // once. Narrating the tool calls is what makes the wait legible.
273	            const line = narrateTool(block.name, (block.input ?? {}) as Record<string, unknown>);
274	            if (line) yield { type: "progress", text: line };
275	          }
276	        }
277	      } else if (message.type === "result") {
278	        yield { type: "usage", ...meterUsage(message) };
279	      }

279	      }
280	    }
281	
282	    if (opts.signal?.aborted) return;
283	
284	    // Diff the directory back into write/delete events so the caller persists
285	    // exactly what the API engine would have produced.
286	    const after = await readFileTree(workDir);
287	
288	    for (const [p, content] of Object.entries(after)) {
289	      if (p.startsWith(".reference.")) continue;
290	      const rel = safeRelPath(p);
291	      if (!rel) continue;
292	      if (opts.files[p] === content) continue; // unchanged
293	      if (await opts.onWrite(rel, content)) yield { type: "file", path: rel, action: "write" };
294	    }
295	    for (const p of Object.keys(opts.files)) {
296	      if (p in after) continue;
297	      const rel = safeRelPath(p);
298	      if (!rel) continue;
299	      if (await opts.onDelete(rel)) yield { type: "file", path: rel, action: "delete" };
300	    }
301	  } finally {
302	    // On Windows a just-exited child can hold the dir briefly (EBUSY); retry,
303	    // and never let cleanup failure mask a successful generation.
304	    try {
305	      await rm(workDir, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
306	    } catch {}
307	  }
308	}
