console.log("rates:", Object.keys(m.MODEL_RATES));

// Bootstraps the app's real TypeScript modules into a plain Node script.
//
// The eval harness deliberately calls the SAME code path production uses —
// `runAgent` from lib/agent.ts and `buildSite` from lib/build-site.ts — rather
// than a reimplementation, because a scoreboard that measures a copy of the
// generator measures nothing. Getting those .ts modules loadable from a .mjs
// script under bare Node (no bundler, no ts-node, no new dependencies) needs
// three fixes, all of them here:
//
//   1. Node 22.6+/24 strips TypeScript types natively, but its ESM resolver
//      still demands full specifiers. lib/agent.ts imports "./models" with no
//      extension, which Node cannot resolve on its own.
//   2. Route handlers use the "@/..." tsconfig path alias, which only a
//      bundler understands.
//   3. buildSite reads KODELY_FOUNDATION_DIR from the environment and silently
//      falls back to a Linux path ("/home/kodely/kodely-foundation") when it is
//      missing — which surfaces as a misleading "Cannot find module" from vite
//      rather than "your env is not loaded". Next.js loads .env for you; a bare
//      node script does not, so we parse it here.
//
// The resolve hook is scoped to files inside the repo and outside
// node_modules, so it can never interfere with how dependencies (many of them
// CommonJS) resolve their own imports.

import { registerHooks } from "node:module";
import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath, pathToFileURL } from "node:url";
import path from "node:path";

/** Repo root: this file lives at <root>/scripts/eval/loader.mjs. */
export const ROOT = path.resolve(import.meta.dirname, "..", "..");

const ROOT_POSIX = ROOT.replace(/\\/g, "/");
const CANDIDATE_EXTENSIONS = [".ts", ".tsx", ".mts", ".js", ".mjs", "/index.ts", "/index.tsx"];

let hooksRegistered = false;
let envLoaded = false;

/**
 * Minimal .env parser. Deliberately not dotenv: the constraint for this harness
 * is Node built-ins only, and the file is a handful of plain KEY=VALUE lines.
 * Existing process.env values win, so `KODELY_ENGINE=api node run.mjs` still
 * overrides the file.
 */
export function loadEnv({ quiet = false } = {}) {
  if (envLoaded) return;
  envLoaded = true;

  const envPath = path.join(ROOT, ".env");
  if (!existsSync(envPath)) {
    if (!quiet) console.warn(`[eval] no .env at ${envPath} — relying on the ambient environment`);
  } else {
    for (const rawLine of readFileSync(envPath, "utf8").split(/\r?\n/)) {
      const line = rawLine.trim();
      if (!line || line.startsWith("#")) continue;
      const eq = line.indexOf("=");
      if (eq === -1) continue;
      const key = line.slice(0, eq).trim();
      let value = line.slice(eq + 1).trim();
      if (
        (value.startsWith('"') && value.endsWith('"') && value.length > 1) ||
        (value.startsWith("'") && value.endsWith("'") && value.length > 1)
      ) {
        value = value.slice(1, -1);
      }
      if (!(key in process.env)) process.env[key] = value;
    }
  }

  // The failure this guard exists for: without it, every single build in the
  // suite fails with a vite "Cannot find module" that points nowhere near the
  // real cause. Fail loudly and early instead of 28 times, confusingly.
  const foundation = process.env.KODELY_FOUNDATION_DIR;
  if (!foundation) {
    throw new Error(
      "KODELY_FOUNDATION_DIR is not set. buildSite would fall back to the Linux " +
        "default path and every build would fail. Set it in .env (it points at the " +
        "checkout produced by scripts/install-foundation.mjs).",
    );
  }
  if (!existsSync(path.join(foundation, "node_modules"))) {
    throw new Error(
      `KODELY_FOUNDATION_DIR=${foundation} has no node_modules. ` +
        "Run `node scripts/install-foundation.mjs` first — buildSite symlinks that tree " +
        "instead of running npm install per generation.",
    );
  }
}

function isProjectSource(parentURL) {
  if (!parentURL || !parentURL.startsWith("file:")) return false;
  const p = fileURLToPath(parentURL).replace(/\\/g, "/");
  return p.startsWith(ROOT_POSIX) && !p.includes("/node_modules/");
}

/** Teach Node's resolver about extensionless imports and the "@/" alias. */
export function registerTsResolution() {
  if (hooksRegistered) return;
  hooksRegistered = true;

  registerHooks({
    resolve(specifier, context, nextResolve) {
      if (!isProjectSource(context.parentURL)) return nextResolve(specifier, context);

      const parentDir = path.dirname(fileURLToPath(context.parentURL));
      let spec = specifier;

      if (spec.startsWith("@/")) {
        const abs = path.join(ROOT, spec.slice(2));
        spec = "./" + path.relative(parentDir, abs).replace(/\\/g, "/");
      }

      if (!spec.startsWith("./") && !spec.startsWith("../")) {
        return nextResolve(specifier, context);
      }

      const abs = path.resolve(parentDir, spec);
      if (path.extname(abs) && existsSync(abs)) return nextResolve(spec, context);

      for (const ext of CANDIDATE_EXTENSIONS) {
        if (existsSync(abs + ext)) return nextResolve(pathToFileURL(abs + ext).href, context);
      }
      return nextResolve(spec, context);
    },
  });
}

/** Node's own type-stripping and typeless-package warnings are just noise here. */
export function quietNodeWarnings() {
  process.removeAllListeners("warning");
  process.on("warning", (warning) => {
    const name = warning.name ?? "";
    const code = /** @type {{ code?: string }} */ (warning).code ?? "";
    if (code === "MODULE_TYPELESS_PACKAGE_JSON") return;
    if (name === "ExperimentalWarning") return;
    console.warn(warning.stack ?? String(warning));
  });
}

const importFromRoot = (rel) => import(pathToFileURL(path.join(ROOT, rel)).href);

/**
 * Loads the production generation modules. Note what is NOT loaded: lib/db.ts,
 * lib/credits.ts and lib/events.ts all instantiate Prisma at module scope, and
 * the harness must never touch the application database. costMicros is
 * therefore re-derived from lib/models.ts's rate card in score.mjs rather than
 * imported from lib/credits.ts.
 */
export async function loadKodely({ quiet = false } = {}) {
  quietNodeWarnings();
  loadEnv({ quiet });
  registerTsResolution();

  const [agent, buildSiteMod, foundation, models] = await Promise.all([
    importFromRoot("lib/agent.ts"),
    importFromRoot("lib/build-site.ts"),
    importFromRoot("lib/foundation.ts"),
    importFromRoot("lib/models.ts"),
  ]);

  return {
    runAgent: agent.runAgent,
    normalizePath: agent.normalizePath,
    ENGINE: agent.ENGINE,
    buildSite: buildSiteMod.buildSite,
    BuildError: buildSiteMod.BuildError,
    FOUNDATION_FILES: foundation.FOUNDATION_FILES,
    MODELS: models.MODELS,
    EFFORT: models.EFFORT,
    MODEL_RATES: models.MODEL_RATES,
  };
}

// Deterministic scoring of one generated site. No model call, no network.
//
// Every check here is cheap, repeatable and answers a question someone would
// actually ask about a shipped page. The bar for including a check was: could
// this fail on a real generation, and would a human agree that failing it is
// worse? Anything that came down to taste was left out — taste needs a judge,
// and a judge is a different, more expensive instrument than this one.
//
// Checks return one of:
//   "pass" / "fail" — counted in the score
//   "skip"          — not applicable to this fixture, excluded from the
//                     denominator (e.g. the html-lang check only runs on a
//                     fixture that declares an expected language)
//   "error"         — the input needed for the check was missing (usually
//                     because the build failed), counted as a fail so a broken
//                     build never scores well by omission.

/** Rough guide only — see MODEL_RATES in lib/models.ts for the real card. */
export function costMicros(rates, model, usage) {
  // Deliberately duplicated from lib/credits.ts rather than imported: that
  // module instantiates Prisma at module scope, and this harness must never
  // open a connection to the application database. Keep the arithmetic in sync
  // with costMicros() there — MODEL_RATES is USD per MILLION tokens, which is
  // numerically already micro-dollars per token, so there is no /1e6.
  const rate = rates[model] ?? rates.default;
  return Math.round(
    rate.input * (usage.inputTokens ?? 0) +
      rate.output * (usage.outputTokens ?? 0) +
      rate.cacheRead * (usage.cacheReadTokens ?? 0) +
      rate.cacheWrite * (usage.cacheWriteTokens ?? 0),
  );
}

/** One credit = $0.002 of model spend. Mirrors MICROS_PER_CREDIT in lib/credits.ts. */
export const MICROS_PER_CREDIT = 2_000;
export const creditsFor = (micros) => Math.max(1, Math.ceil(micros / MICROS_PER_CREDIT));

export const CHECK_IDS = [
  "title",
  "meta-description",
  "og-tags",
  "no-placeholder-text",
  "no-external-requests",
  "responsive",
  "component-count",
  "html-lang",
];

const FOUNDATION_TITLE = "Kodely Site";

// ── small HTML helpers (regex, not a parser — the input is vite's own output) ──

function textOfTitle(html) {
  const m = /<title[^>]*>([\s\S]*?)<\/title>/i.exec(html ?? "");
  return m ? m[1].replace(/\s+/g, " ").trim() : null;
}

/** Reads a meta tag's content by name= or property=, in either attribute order. */
function metaContent(html, key) {
  const re = new RegExp(`<meta\\b[^>]*?\\b(?:name|property)\\s*=\\s*["']${key}["'][^>]*>`, "i");
  const tag = re.exec(html ?? "")?.[0];
  if (!tag) return null;
  const c = /\bcontent\s*=\s*"([^"]*)"/i.exec(tag) ?? /\bcontent\s*=\s*'([^']*)'/i.exec(tag);
  return c ? c[1].trim() : null;
}

function htmlLang(html) {
  const m = /<html\b[^>]*\blang\s*=\s*["']([^"']+)["']/i.exec(html ?? "");
  return m ? m[1].trim().toLowerCase() : null;
}

const byExt = (files, ext) =>
  Object.entries(files ?? {}).filter(([p]) => p.toLowerCase().endsWith(ext));

// ── the checks ────────────────────────────────────────────────────────────────

function checkTitle(ctx) {
  const title = textOfTitle(ctx.indexHtml);
  if (!ctx.indexHtml) return { status: "error", detail: "no dist/index.html (build failed?)" };
  if (!title) return { status: "fail", detail: "no <title> element" };
  if (title === FOUNDATION_TITLE) {
    return { status: "fail", detail: `left the foundation placeholder "${FOUNDATION_TITLE}"` };
  }
  if (title.length < 3) return { status: "fail", detail: `title too short: "${title}"` };
  if (title.length > 70) return { status: "fail", detail: `title ${title.length} chars (aim under ~60)` };
  return { status: "pass", detail: `"${title}" (${title.length} chars)` };
}

// 50-200 chars is the window where a description is a real sentence about the
// business and still survives a search result without truncation. Outside it,
// it is either missing-in-practice or an essay.
function checkMetaDescription(ctx) {
  if (!ctx.indexHtml) return { status: "error", detail: "no dist/index.html (build failed?)" };
  const desc = metaContent(ctx.indexHtml, "description");
  if (!desc) return { status: "fail", detail: "no meta description" };
  if (desc.length < 50) return { status: "fail", detail: `only ${desc.length} chars` };
  if (desc.length > 200) return { status: "fail", detail: `${desc.length} chars (over 200)` };
  return { status: "pass", detail: `${desc.length} chars` };
}

function checkOgTags(ctx) {
  if (!ctx.indexHtml) return { status: "error", detail: "no dist/index.html (build failed?)" };
  const title = metaContent(ctx.indexHtml, "og:title");
  const desc = metaContent(ctx.indexHtml, "og:description");
  const missing = [];
  if (!title) missing.push("og:title");
  if (!desc) missing.push("og:description");
  if (missing.length) return { status: "fail", detail: `empty: ${missing.join(", ")}` };
  if (title === FOUNDATION_TITLE) return { status: "fail", detail: "og:title is the placeholder" };
  return { status: "pass", detail: "og:title and og:description set" };
}

const PLACEHOLDER_PATTERNS = [
  [/lorem\s+ipsum/i, "Lorem ipsum"],
  [/dolor\s+sit\s+amet/i, "lorem filler"],
  [/your\s+(title|name|headline|text|logo|company|business|tagline)\s+here/i, "'Your ... here'"],
  [/\b(headline|text|content|description)\s+goes\s+here\b/i, "'... goes here'"],
  [/\bplaceholder\s+(text|content|copy)\b/i, "'placeholder text'"],
  [/\binsert\s+(your|text|content)\b/i, "'insert ...'"],
  [/\bsample\s+(text|content|heading)\b/i, "'sample text'"],
  [/\bKodely\s+Site\b/, "the foundation placeholder title"],
  [/\bTODO\b/, "a TODO left in the output"],
];

const COMING_SOON = /\bcoming\s+soon\b/i;

function checkPlaceholderText(ctx) {
  // Source is scanned as well as dist because a placeholder inside a component
  // that happens to be conditionally rendered still ships to the customer.
  const haystacks = [
    ...byExt(ctx.dist, ".html"),
    ...Object.entries(ctx.source).filter(([p]) => /\.(tsx|jsx|html|css|md)$/i.test(p)),
  ];
  if (!haystacks.length) return { status: "error", detail: "nothing to scan" };

  const hits = [];
  for (const [path, content] of haystacks) {
    for (const [re, label] of PLACEHOLDER_PATTERNS) {
      if (re.test(content)) hits.push(`${label} in ${path}`);
    }
    // "Coming soon" is only a defect when nobody asked for it. A coming-soon
    // page that says "coming soon" is the correct answer, and a rubric that
    // marks it wrong would push the prompt in exactly the wrong direction.
    if (!ctx.allowComingSoon && COMING_SOON.test(content)) {
      hits.push(`"coming soon" in ${path} (not requested)`);
    }
  }
  const unique = [...new Set(hits)];
  return unique.length
    ? { status: "fail", detail: unique.slice(0, 4).join("; ") }
    : { status: "pass", detail: "no placeholder copy found" };
}

// Correctness, not style: the published CSP blocks every external host, so any
// of these silently fails to load on the live site.
const EXTERNAL_HTML_PATTERNS = [
  [/<script\b[^>]*\bsrc\s*=\s*["']?(?:https?:)?\/\//i, "<script src=http>"],
  [/<link\b[^>]*\bhref\s*=\s*["']?(?:https?:)?\/\//i, "<link href=http>"],
  [/<img\b[^>]*\bsrc\s*=\s*["']?(?:https?:)?\/\//i, "<img src=http>"],
  [/<iframe\b[^>]*\bsrc\s*=\s*["']?(?:https?:)?\/\//i, "<iframe src=http>"],
  [/<(?:source|video|audio|track)\b[^>]*\bsrc\s*=\s*["']?(?:https?:)?\/\//i, "<media src=http>"],
];
const EXTERNAL_CSS_PATTERNS = [
  [/@import\s+(?:url\()?\s*["']?(?:https?:)?\/\//i, "@import from a remote host"],
  [/url\(\s*["']?(?:https?:)?\/\/(?!localhost)/i, "css url() to a remote host"],
];
// JSX equivalents. Deliberately does NOT flag <a href="https://..."> — an
// outbound hyperlink is not a request the page makes, and the band and shop
// fixtures legitimately link out.
const EXTERNAL_JSX_PATTERNS = [
  [/\bsrc\s*=\s*\{?\s*["'`](?:https?:)?\/\//i, "src= pointing at a remote host"],
  [/\bsrcSet\s*=\s*\{?\s*["'`](?:https?:)?\/\//i, "srcSet pointing at a remote host"],
  [/\bfetch\s*\(\s*["'`](?:https?:)?\/\//i, "fetch() to a remote host"],
  [/fonts\.(googleapis|gstatic)\.com/i, "Google Fonts"],
];

function checkExternalRequests(ctx) {
  const hits = [];
  const scan = (entries, patterns) => {
    for (const [path, content] of entries) {
      for (const [re, label] of patterns) {
        const m = re.exec(content);
        if (m) hits.push(`${label} in ${path}`);
      }
    }
  };

  const htmlEntries = [...byExt(ctx.dist, ".html")];
  if (ctx.source["index.html"]) htmlEntries.push(["index.html (source)", ctx.source["index.html"]]);
  scan(htmlEntries, EXTERNAL_HTML_PATTERNS);
  scan([...byExt(ctx.dist, ".css"), ...byExt(ctx.source, ".css")], EXTERNAL_CSS_PATTERNS);
  // Bundled JS is not scanned: React ships documentation URLs in its own error
  // strings, which would be a permanent false positive. The JSX source is the
  // honest place to look for a remote asset the agent wrote.
  scan(
    Object.entries(ctx.source).filter(([p]) => /\.(tsx|jsx|ts|js)$/i.test(p)),
    EXTERNAL_JSX_PATTERNS,
  );

  const unique = [...new Set(hits)];
  return unique.length
    ? { status: "fail", detail: unique.slice(0, 4).join("; ") }
    : { status: "pass", detail: "no external asset requests" };
}

const BREAKPOINT_CLASS = /\b(sm|md|lg|xl|2xl):[a-z[]/;
const WIDTH_MEDIA_QUERY = /@media[^{]*\((?:min|max)-width/i;

function checkResponsive(ctx) {
  // A width-based media query, specifically: Tailwind's preflight emits
  // @media (hover: hover) unconditionally, so a bare "@media" test would pass
  // even for a page with no responsive work at all.
  const css = byExt(ctx.dist, ".css").map(([, c]) => c).join("\n");
  if (WIDTH_MEDIA_QUERY.test(css)) {
    return { status: "pass", detail: "width-based media queries in the compiled CSS" };
  }
  const sourceHit = Object.entries(ctx.source).find(
    ([p, c]) => /\.(tsx|jsx)$/i.test(p) && BREAKPOINT_CLASS.test(c),
  );
  if (sourceHit) {
    return { status: "pass", detail: `Tailwind breakpoint classes (${sourceHit[0]})` };
  }
  if (!css && !Object.keys(ctx.source).length) {
    return { status: "error", detail: "no CSS or source to inspect" };
  }
  return { status: "fail", detail: "no width media queries and no breakpoint classes" };
}

function checkComponentCount(ctx) {
  // Counts components the AGENT wrote. The foundation already ships four UI
  // primitives under src/components/ui/, so a naive count of that directory
  // would pass for a site that is one giant App.tsx — which is the exact
  // failure this check exists to catch.
  const authored = Object.keys(ctx.source).filter(
    (p) =>
      /^src\/.+\.(tsx|jsx)$/i.test(p) &&
      p !== "src/main.tsx" &&
      p !== "src/App.tsx" &&
      !ctx.foundationPaths.has(p),
  );
  const appLines = (ctx.source["src/App.tsx"] ?? "").split("\n").length;
  const detail = `${authored.length} authored component file(s), App.tsx ${appLines} lines`;
  if (!Object.keys(ctx.source).length) return { status: "error", detail: "no source files" };
  return authored.length > 1 ? { status: "pass", detail } : { status: "fail", detail };
}

function checkHtmlLang(ctx) {
  if (!ctx.expectLang) return { status: "skip", detail: "no expected language for this fixture" };
  if (!ctx.indexHtml) return { status: "error", detail: "no dist/index.html (build failed?)" };
  const lang = htmlLang(ctx.indexHtml);
  if (!lang) return { status: "fail", detail: "no lang attribute on <html>" };
  const ok = lang === ctx.expectLang || lang.startsWith(`${ctx.expectLang}-`);
  return ok
    ? { status: "pass", detail: `lang="${lang}"` }
    : { status: "fail", detail: `lang="${lang}", expected "${ctx.expectLang}"` };
}

const CHECKS = {
  title: checkTitle,
  "meta-description": checkMetaDescription,
  "og-tags": checkOgTags,
  "no-placeholder-text": checkPlaceholderText,
  "no-external-requests": checkExternalRequests,
  responsive: checkResponsive,
  "component-count": checkComponentCount,
  "html-lang": checkHtmlLang,
};

/**
 * @param {object} args
 * @param {Record<string,string>} args.source  final source FileMap
 * @param {Record<string,string>|null} args.dist compiled output, or null if the build failed
 * @param {object} args.fixture the fixture entry from prompts.json
 * @param {Set<string>} args.foundationPaths paths shipped by lib/foundation.ts
 */
export function scoreSite({ source, dist, fixture, foundationPaths }) {
  const ctx = {
    source: source ?? {},
    dist: dist ?? {},
    indexHtml: dist?.["index.html"] ?? null,
    foundationPaths: foundationPaths ?? new Set(),
    expectLang: fixture?.expect?.lang ?? null,
    allowComingSoon:
      Boolean(fixture?.expect?.allowComingSoon) ||
      /coming\s+soon|launch(?:ing)?\s+soon/i.test(fixture?.prompt ?? ""),
  };

  const checks = CHECK_IDS.map((id) => {
    let result;
    try {
      result = CHECKS[id](ctx);
    } catch (err) {
      result = { status: "error", detail: `check threw: ${err?.message ?? err}` };
    }
    return { id, status: result.status, detail: result.detail };
  });

  const applicable = checks.filter((c) => c.status !== "skip");
  const passed = applicable.filter((c) => c.status === "pass").length;

  return {
    checks,
    passed,
    applicable: applicable.length,
    score: applicable.length ? Number((passed / applicable.length).toFixed(4)) : 0,
  };
}

#!/usr/bin/env node
// Golden-set evaluation runner.
//
//   node scripts/eval/run.mjs --only restaurant-italian
//   node scripts/eval/run.mjs --difficulty awkward --concurrency 2 --yes
//   node scripts/eval/run.mjs --list
//
// For each fixture it drives the REAL generation path — runAgent from
// lib/agent.ts, which dispatches to whichever engine KODELY_ENGINE selects —
// then compiles the result with buildSite from lib/build-site.ts, mirroring the
// repair loop in app/api/generate/route.ts. It records whether the site
// compiled first try, how many repairs it took, tokens, imputed cost, wall
// time, files written, and a deterministic static score, into a timestamped
// JSON file under scripts/eval/results/.
//
// It never touches the database. The onWrite/onDelete callbacks that the route
// points at Prisma are pointed at an in-memory FileMap here, and no module that
// instantiates a Prisma client is ever imported (see loader.mjs).
//
// EVERY RUN COSTS REAL TOKENS. The suite is ~30 first builds at `high` effort;
// running all of it is a deliberate act, which is why anything over
// CONFIRM_THRESHOLD fixtures refuses to start without --yes.

import { mkdir, writeFile, readFile } from "node:fs/promises";
import { execFileSync } from "node:child_process";
import path from "node:path";
import { performance } from "node:perf_hooks";
import { loadKodely, ROOT } from "./loader.mjs";
import { scoreSite, costMicros, creditsFor } from "./score.mjs";

const EVAL_DIR = import.meta.dirname;
const RESULTS_DIR = path.join(EVAL_DIR, "results");

// Mirrors MAX_BUILD_ATTEMPTS in app/api/generate/route.ts. If that changes,
// change it here — the harness is only honest while it repairs the same number
// of times production does.
const MAX_BUILD_ATTEMPTS = 2;

/** Above this many fixtures, --yes is required. Generation costs real money. */
const CONFIRM_THRESHOLD = 5;

const DEFAULT_TIMEOUT_MS = 10 * 60_000;

// ── CLI ───────────────────────────────────────────────────────────────────────

function parseArgs(argv) {
  const opts = {
    only: [],
    category: null,
    difficulty: null,
    limit: null,
    concurrency: 2,
    label: "run",
    engine: null,
    saveSources: false,
    yes: false,
    list: false,
    out: null,
    timeoutMs: DEFAULT_TIMEOUT_MS,
  };
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    const next = () => {
      const v = argv[++i];
      if (v === undefined) throw new Error(`${arg} needs a value`);
      return v;
    };
    switch (arg) {
      case "--only": opts.only.push(...next().split(",").map((s) => s.trim()).filter(Boolean)); break;
      case "--category": opts.category = next(); break;
      case "--difficulty": opts.difficulty = next(); break;
      case "--limit": opts.limit = Number(next()); break;
      case "--concurrency": opts.concurrency = Math.max(1, Number(next())); break;
      case "--label": opts.label = next().replace(/[^A-Za-z0-9._-]/g, "-"); break;
      case "--engine": opts.engine = next(); break;
      case "--timeout": opts.timeoutMs = Number(next()); break;
      case "--out": opts.out = next(); break;
      case "--save-sources": opts.saveSources = true; break;
      case "--yes": case "-y": opts.yes = true; break;
      case "--list": opts.list = true; break;
      case "--help": case "-h": opts.help = true; break;
      default:
        throw new Error(`Unknown flag: ${arg}`);
    }
  }
  return opts;
}

const HELP = `Kodely golden-set evaluation runner

  node scripts/eval/run.mjs [flags]

  --only <id[,id]>    run just these fixtures (repeatable)
  --category <name>   filter by fixture category (restaurant, saas, adversarial, ...)
  --difficulty <name> filter by difficulty (standard | awkward)
  --limit <n>         cap the number of fixtures after filtering
  --concurrency <n>   parallel generations (default 2 — these are expensive)
  --label <name>      goes in the result filename, e.g. --label baseline
  --engine <api|sdk>  override KODELY_ENGINE for this run
  --timeout <ms>      per-fixture wall-clock budget (default 600000)
  --save-sources      embed the generated source files in the result JSON
  --out <file>        write the result here instead of scripts/eval/results/
  --list              print the fixture set and exit, generating nothing
  -y, --yes           required to run more than ${CONFIRM_THRESHOLD} fixtures

Compare two result files with:
  node scripts/eval/report.mjs <before.json> <after.json>
`;

// ── helpers ───────────────────────────────────────────────────────────────────

const fmtMs = (ms) => `${(ms / 1000).toFixed(1)}s`;

function gitInfo() {
  const git = (args) => execFileSync("git", args, { cwd: ROOT, encoding: "utf8" }).trim();
  try {
    return { commit: git(["rev-parse", "--short", "HEAD"]), dirty: git(["status", "--porcelain"]).length > 0 };
  } catch {
    return { commit: null, dirty: null };
  }
}

/** Bounded worker pool. Keeps `limit` generations in flight, in fixture order. */
async function pool(items, limit, worker) {
  const results = new Array(items.length);
  let cursor = 0;
  const runners = Array.from({ length: Math.min(limit, items.length) }, async () => {
    while (true) {
      const i = cursor++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
    }
  });
  await Promise.all(runners);
  return results;
}

// ── one fixture ───────────────────────────────────────────────────────────────

async function runFixture(fixture, kodely, opts) {
  const { runAgent, normalizePath, buildSite, BuildError, FOUNDATION_FILES, MODEL_RATES } = kodely;

  const startedAt = new Date().toISOString();
  const t0 = performance.now();

  // The whole project lives here. This is what the route keeps in Prisma; the
  // harness keeps it in memory so a run can never write to the app database.
  const files = { ...FOUNDATION_FILES };
  const foundationPaths = new Set(Object.keys(FOUNDATION_FILES));

  let filesWritten = 0;
  let repairAttempts = 0;
  let model = "";
  let reply = "";
  const totals = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 };
  const writtenPaths = new Set();

  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), opts.timeoutMs);

  let dist = null;
  let error = null;
  let buildErrors = [];

  try {
    let request = fixture.prompt;

    for (let attempt = 1; attempt <= MAX_BUILD_ATTEMPTS; attempt++) {
      if (controller.signal.aborted) break;

      const generator = runAgent({
        history: [],
        request,
        files: { ...files },
        // Always "create": the golden set measures first-build quality, which
        // is the metric the roadmap gates on. Edit-quality would be a second,
        // separate fixture set with a starting FileMap per entry.
        kind: "create",
        signal: controller.signal,
        onWrite: async (p, content) => {
          if (!normalizePath(p)) return false;
          files[p] = content;
          writtenPaths.add(p);
          filesWritten++;
          return true;
        },
        onDelete: async (p) => {
          if (!(p in files)) return false;
          delete files[p];
          return true;
        },
      });

      for await (const event of generator) {
        if (event.type === "text") reply += event.text;
        else if (event.type === "usage") {
          model = event.model;
          totals.inputTokens += event.inputTokens;
          totals.outputTokens += event.outputTokens;
          totals.cacheReadTokens += event.cacheReadTokens;
          totals.cacheWriteTokens += event.cacheWriteTokens;
        }
      }

      if (controller.signal.aborted) break;

      try {
        dist = await buildSite({ ...files });
        break;
      } catch (err) {
        const message = err instanceof BuildError ? err.message : String(err);
        buildErrors.push(message);
        if (attempt >= MAX_BUILD_ATTEMPTS) {
          error = message;
          break;
        }
        repairAttempts++;
        // Verbatim from app/api/generate/route.ts — a repair prompt that
        // differs from production's would measure the wrong thing.
        request = `The last change failed to build. Fix it and keep the rest of the change. Build error:\n${message}`;
      }
    }

    if (controller.signal.aborted && !dist) {
      error = error ?? `Timed out after ${opts.timeoutMs}ms`;
    }
  } catch (err) {
    error = err?.message ?? String(err);
  } finally {
    clearTimeout(timer);
  }

  const wallMs = Math.round(performance.now() - t0);
  const micros = costMicros(MODEL_RATES, model, totals);
  const scored = scoreSite({ source: files, dist, fixture, foundationPaths });

  return {
    id: fixture.id,
    category: fixture.category,
    difficulty: fixture.difficulty,
    prompt: fixture.prompt,
    startedAt,
    ok: Boolean(dist),
    error,
    // The headline metric the roadmap gates on. `false` when the build never
    // compiled at all, so a total failure is never mistaken for a green build.
    compiledFirstTry: Boolean(dist) && repairAttempts === 0,
    repairAttempts,
    buildErrors: buildErrors.map((m) => m.slice(0, 600)),
    wallMs,
    filesWritten,
    filesWrittenPaths: [...writtenPaths].sort(),
    sourceFileCount: Object.keys(files).length,
    distFileCount: dist ? Object.keys(dist).length : 0,
    model,
    usage: totals,
    costMicros: micros,
    credits: creditsFor(micros),
    replyChars: reply.trim().length,
    score: scored,
    ...(opts.saveSources ? { source: files } : {}),
  };
}

// ── aggregate ─────────────────────────────────────────────────────────────────

export function aggregate(results) {
  const n = results.length;
  const sum = (fn) => results.reduce((acc, r) => acc + (fn(r) || 0), 0);
  const mean = (fn) => (n ? sum(fn) / n : 0);
  const okResults = results.filter((r) => r.ok);

  const checkTotals = {};
  for (const r of results) {
    for (const c of r.score?.checks ?? []) {
      const t = (checkTotals[c.id] ??= { pass: 0, fail: 0, error: 0, skip: 0 });
      t[c.status] = (t[c.status] ?? 0) + 1;
    }
  }

  return {
    count: n,
    okCount: okResults.length,
    okRate: n ? okResults.length / n : 0,
    greenFirstTryCount: results.filter((r) => r.compiledFirstTry).length,
    // The kill-criterion metric, over ALL fixtures — a build that never
    // compiled counts against it, exactly as it would for a customer.
    greenFirstTryRate: n ? results.filter((r) => r.compiledFirstTry).length / n : 0,
    meanRepairAttempts: mean((r) => r.repairAttempts),
    meanScore: mean((r) => r.score?.score ?? 0),
    meanScoreOk: okResults.length
      ? okResults.reduce((a, r) => a + (r.score?.score ?? 0), 0) / okResults.length
      : 0,
    meanWallMs: mean((r) => r.wallMs),
    totalCostMicros: sum((r) => r.costMicros),
    meanCostMicros: mean((r) => r.costMicros),
    totalCredits: sum((r) => r.credits),
    meanCredits: mean((r) => r.credits),
    totalOutputTokens: sum((r) => r.usage?.outputTokens),
    meanFilesWritten: mean((r) => r.filesWritten),
    checkTotals,
  };
}

// ── main ──────────────────────────────────────────────────────────────────────

async function main() {
  let opts;
  try {
    opts = parseArgs(process.argv.slice(2));
  } catch (err) {
    console.error(`${err.message}\n\n${HELP}`);
    process.exit(2);
  }
  if (opts.help) {
    console.log(HELP);
    return;
  }

  const fixtureSet = JSON.parse(await readFile(path.join(EVAL_DIR, "prompts.json"), "utf8"));
  const all = fixtureSet.fixtures;

  let selected = all;
  if (opts.only.length) {
    const known = new Set(all.map((f) => f.id));
    const missing = opts.only.filter((id) => !known.has(id));
    if (missing.length) {
      console.error(`Unknown fixture id(s): ${missing.join(", ")}`);
      process.exit(2);
    }
    selected = all.filter((f) => opts.only.includes(f.id));
  }
  if (opts.category) selected = selected.filter((f) => f.category === opts.category);
  if (opts.difficulty) selected = selected.filter((f) => f.difficulty === opts.difficulty);
  if (opts.limit) selected = selected.slice(0, opts.limit);

  if (opts.list) {
    console.log(`${all.length} fixtures (${selected.length} selected)\n`);
    for (const f of selected) {
      const mark = f.difficulty === "awkward" ? "*" : " ";
      console.log(`${mark} ${f.id.padEnd(32)} ${f.category.padEnd(14)} ${f.prompt.slice(0, 70)}...`);
    }
    console.log(`\n* = deliberately awkward fixture`);
    return;
  }

  if (!selected.length) {
    console.error("No fixtures matched the filters.");
    process.exit(2);
  }

  if (selected.length > CONFIRM_THRESHOLD && !opts.yes) {
    console.error(
      `Refusing to run ${selected.length} fixtures without --yes.\n` +
        `Each one is a full first build against a real model. Narrow it with ` +
        `--only/--difficulty/--limit, or pass --yes if you mean it.`,
    );
    process.exit(2);
  }

  if (opts.engine) process.env.KODELY_ENGINE = opts.engine;

  const kodely = await loadKodely();

  const runStartedAt = new Date();
  const stamp = runStartedAt.toISOString().replace(/[:.]/g, "-").replace("Z", "Z");
  const outPath = opts.out
    ? path.resolve(opts.out)
    : path.join(RESULTS_DIR, `${stamp}-${opts.label}.json`);

  console.log(
    `[eval] ${selected.length} fixture(s), engine=${kodely.ENGINE}, ` +
      `builder=${kodely.MODELS.builder}, effort(create)=${kodely.EFFORT.create}, ` +
      `concurrency=${opts.concurrency}`,
  );
  console.log(`[eval] results -> ${outPath}\n`);

  let done = 0;
  const results = await pool(selected, opts.concurrency, async (fixture) => {
    const result = await runFixture(fixture, kodely, opts);
    done++;
    const verdict = !result.ok
      ? "FAILED"
      : result.compiledFirstTry
        ? "green"
        : `repaired x${result.repairAttempts}`;
    console.log(
      `[${String(done).padStart(2)}/${selected.length}] ${result.id.padEnd(32)} ` +
        `${verdict.padEnd(13)} score ${(result.score.score * 100).toFixed(0).padStart(3)}% ` +
        `${String(result.score.passed)}/${result.score.applicable} checks  ` +
        `${fmtMs(result.wallMs).padStart(7)}  ${result.credits} cr` +
        (result.error ? `  :: ${result.error.split("\n")[0].slice(0, 90)}` : ""),
    );
    return result;
  });

  const payload = {
    schemaVersion: 1,
    label: opts.label,
    startedAt: runStartedAt.toISOString(),
    finishedAt: new Date().toISOString(),
    engine: kodely.ENGINE,
    models: { ...kodely.MODELS },
    effort: { ...kodely.EFFORT },
    concurrency: opts.concurrency,
    fixtureSetVersion: fixtureSet.version,
    selectedIds: selected.map((f) => f.id),
    git: gitInfo(),
    node: process.version,
    aggregate: aggregate(results),
    results,
  };

  await mkdir(path.dirname(outPath), { recursive: true });
  await writeFile(outPath, JSON.stringify(payload, null, 2), "utf8");

  const a = payload.aggregate;
  console.log(
    `\n[eval] green-build-first-try ${(a.greenFirstTryRate * 100).toFixed(0)}% ` +
      `(${a.greenFirstTryCount}/${a.count})   compiled ${a.okCount}/${a.count}   ` +
      `mean score ${(a.meanScore * 100).toFixed(0)}%   ` +
      `mean ${fmtMs(a.meanWallMs)}   ${a.totalCredits} credits total`,
  );
  console.log(`[eval] wrote ${outPath}`);
  console.log(`[eval] compare with: node scripts/eval/report.mjs <baseline.json> ${path.relative(ROOT, outPath).replace(/\\/g, "/")}`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

#!/usr/bin/env node
// Diff two eval runs. This is the actual point of the harness: a single run
// tells you almost nothing, because there is no absolute standard for "a good
// restaurant page". A DIFF between two runs of the same fixture set tells you
// whether the prompt change you just made helped.
//
//   node scripts/eval/report.mjs results/<before>.json results/<after>.json
//   node scripts/eval/report.mjs results/<run>.json            # summarise one run
//   node scripts/eval/report.mjs a.json b.json --fail-on-regression   # for CI
//   node scripts/eval/report.mjs a.json b.json --json
//
// Runs are noisy: generation is sampled, so a single fixture flipping is not
// evidence. The aggregate lines are what to read; the per-fixture list is for
// finding out WHY an aggregate moved.

import { readFile } from "node:fs/promises";
import path from "node:path";

const HELP = `Compare two golden-set eval runs.

  node scripts/eval/report.mjs <before.json> <after.json> [flags]
  node scripts/eval/report.mjs <run.json>

  --fail-on-regression  exit 1 if any fixture got worse (for CI)
  --json                emit the comparison as JSON instead of a table
  --all                 list every fixture, not just the ones that changed
`;

// Which direction is an improvement, per metric.
const METRICS = [
  { key: "greenFirstTryRate", label: "green build first try", fmt: pct, better: "up" },
  { key: "okRate", label: "compiled at all", fmt: pct, better: "up" },
  { key: "meanScore", label: "mean static score", fmt: pct, better: "up" },
  { key: "meanRepairAttempts", label: "mean repair attempts", fmt: (v) => v.toFixed(2), better: "down" },
  { key: "meanCredits", label: "mean credits / build", fmt: (v) => v.toFixed(0), better: "down" },
  { key: "meanWallMs", label: "mean wall time", fmt: (v) => `${(v / 1000).toFixed(1)}s`, better: "down" },
  { key: "meanFilesWritten", label: "mean files written", fmt: (v) => v.toFixed(1), better: "flat" },
];

function pct(v) {
  return `${(v * 100).toFixed(0)}%`;
}

function parseArgs(argv) {
  const files = [];
  const opts = { failOnRegression: false, json: false, all: false };
  for (const arg of argv) {
    if (arg === "--fail-on-regression") opts.failOnRegression = true;
    else if (arg === "--json") opts.json = true;
    else if (arg === "--all") opts.all = true;
    else if (arg === "--help" || arg === "-h") opts.help = true;
    else if (arg.startsWith("--")) throw new Error(`Unknown flag: ${arg}`);
    else files.push(arg);
  }
  return { files, opts };
}

const load = async (p) => JSON.parse(await readFile(path.resolve(p), "utf8"));
const byId = (run) => new Map(run.results.map((r) => [r.id, r]));

function checkMap(result) {
  return new Map((result.score?.checks ?? []).map((c) => [c.id, c.status]));
}

/**
 * A fixture's verdict, worst to best. Comparing these ranks is what makes
 * "got worse" mean something more useful than a score delta alone: dropping
 * from green to repaired matters more than losing one static check.
 */
function rank(r) {
  if (!r.ok) return 0;
  if (!r.compiledFirstTry) return 1;
  return 2;
}

function compareFixture(before, after) {
  const rankDelta = rank(after) - rank(before);
  const scoreDelta = (after.score?.score ?? 0) - (before.score?.score ?? 0);

  const b = checkMap(before);
  const a = checkMap(after);
  const checksLost = [];
  const checksGained = [];
  for (const [id, status] of a) {
    const prev = b.get(id);
    if (prev === "pass" && status !== "pass" && status !== "skip") checksLost.push(id);
    if (prev && prev !== "pass" && prev !== "skip" && status === "pass") checksGained.push(id);
  }

  let verdict = "same";
  if (rankDelta < 0 || (rankDelta === 0 && (checksLost.length > checksGained.length || scoreDelta < -0.001))) {
    verdict = "worse";
  } else if (rankDelta > 0 || checksGained.length > checksLost.length || scoreDelta > 0.001) {
    verdict = "better";
  }

  return {
    id: after.id,
    verdict,
    rankDelta,
    scoreDelta,
    checksLost,
    checksGained,
    before: {
      ok: before.ok,
      compiledFirstTry: before.compiledFirstTry,
      repairAttempts: before.repairAttempts,
      score: before.score?.score ?? 0,
      credits: before.credits,
      wallMs: before.wallMs,
    },
    after: {
      ok: after.ok,
      compiledFirstTry: after.compiledFirstTry,
      repairAttempts: after.repairAttempts,
      score: after.score?.score ?? 0,
      credits: after.credits,
      wallMs: after.wallMs,
    },
  };
}

function stateLabel(r) {
  if (!r.ok) return "FAILED";
  if (!r.compiledFirstTry) return `repair x${r.repairAttempts}`;
  return "green";
}

function printSingle(run, opts) {
  const a = run.aggregate;
  console.log(`Run: ${run.label}  (${run.startedAt})`);
  console.log(`Engine ${run.engine} / ${run.models?.builder} / effort ${run.effort?.create}`);
  if (run.git?.commit) console.log(`Commit ${run.git.commit}${run.git.dirty ? " (dirty tree)" : ""}`);
  console.log("");
  for (const m of METRICS) {
    console.log(`  ${m.label.padEnd(24)} ${m.fmt(a[m.key] ?? 0).padStart(8)}`);
  }
  console.log(`  ${"total credits".padEnd(24)} ${String(a.totalCredits).padStart(8)}`);
  console.log("\nStatic checks (pass / applicable):");
  for (const [id, t] of Object.entries(a.checkTotals ?? {})) {
    const applicable = (t.pass ?? 0) + (t.fail ?? 0) + (t.error ?? 0);
    console.log(`  ${id.padEnd(24)} ${String(t.pass ?? 0).padStart(3)} / ${applicable}`);
  }
  console.log("\nPer fixture:");
  const rows = [...run.results].sort((x, y) => (x.score?.score ?? 0) - (y.score?.score ?? 0));
  for (const r of rows) {
    const failing = (r.score?.checks ?? []).filter((c) => c.status === "fail" || c.status === "error");
    console.log(
      `  ${r.id.padEnd(32)} ${stateLabel(r).padEnd(11)} ${pct(r.score?.score ?? 0).padStart(4)}` +
        (failing.length ? `  failing: ${failing.map((c) => c.id).join(", ")}` : ""),
    );
    if (opts.all && r.error) console.log(`      error: ${r.error.split("\n")[0].slice(0, 120)}`);
  }
}

function printComparison(before, after, cmp, opts) {
  const arrow = (delta, better) => {
    if (Math.abs(delta) < 1e-9 || better === "flat") return "  ";
    const good = better === "up" ? delta > 0 : delta < 0;
    return good ? "++" : "--";
  };

  console.log(`BEFORE  ${before.label}  ${before.startedAt}  (${before.aggregate.count} fixtures)`);
  console.log(`AFTER   ${after.label}  ${after.startedAt}  (${after.aggregate.count} fixtures)`);
  if (before.git?.commit || after.git?.commit) {
    console.log(`commit  ${before.git?.commit ?? "?"} -> ${after.git?.commit ?? "?"}`);
  }
  if (before.models?.builder !== after.models?.builder || before.effort?.create !== after.effort?.create) {
    console.log(
      `NOTE    model/effort changed between runs: ` +
        `${before.models?.builder}@${before.effort?.create} -> ${after.models?.builder}@${after.effort?.create}`,
    );
  }
  if (cmp.onlyBefore.length || cmp.onlyAfter.length) {
    console.log(
      `NOTE    fixture sets differ; comparing the ${cmp.shared} in common` +
        (cmp.onlyBefore.length ? `  (only before: ${cmp.onlyBefore.join(", ")})` : "") +
        (cmp.onlyAfter.length ? `  (only after: ${cmp.onlyAfter.join(", ")})` : ""),
    );
  }

  console.log(`\nAGGREGATE  (over the ${cmp.shared} shared fixtures)`);
  console.log(`  ${"metric".padEnd(24)} ${"before".padStart(8)} ${"after".padStart(8)}   delta`);
  for (const m of METRICS) {
    const b = cmp.aggBefore[m.key] ?? 0;
    const a = cmp.aggAfter[m.key] ?? 0;
    const d = a - b;
    console.log(
      `  ${m.label.padEnd(24)} ${m.fmt(b).padStart(8)} ${m.fmt(a).padStart(8)}   ` +
        `${arrow(d, m.better)} ${m.fmt(Math.abs(d))}`,
    );
  }

  console.log(`\nSTATIC CHECKS  (fixtures passing, of those where the check applies)`);
  for (const row of cmp.checks) {
    const mark = row.delta > 0 ? "++" : row.delta < 0 ? "--" : "  ";
    console.log(
      `  ${row.id.padEnd(24)} ${`${row.beforePass}/${row.beforeApplicable}`.padStart(8)} ` +
        `${`${row.afterPass}/${row.afterApplicable}`.padStart(8)}   ${mark} ${row.delta > 0 ? "+" : ""}${row.delta}`,
    );
  }

  const groups = [
    ["WORSE", cmp.fixtures.filter((f) => f.verdict === "worse")],
    ["BETTER", cmp.fixtures.filter((f) => f.verdict === "better")],
  ];
  if (opts.all) groups.push(["UNCHANGED", cmp.fixtures.filter((f) => f.verdict === "same")]);

  for (const [heading, rows] of groups) {
    console.log(`\n${heading}  (${rows.length})`);
    if (!rows.length) {
      console.log("  none");
      continue;
    }
    for (const f of rows) {
      const state =
        f.before.ok !== f.after.ok || f.before.compiledFirstTry !== f.after.compiledFirstTry
          ? `${stateLabel(f.before)} -> ${stateLabel(f.after)}`
          : stateLabel(f.after);
      const parts = [`${pct(f.before.score)} -> ${pct(f.after.score)}`, state];
      if (f.checksLost.length) parts.push(`lost: ${f.checksLost.join(", ")}`);
      if (f.checksGained.length) parts.push(`gained: ${f.checksGained.join(", ")}`);
      console.log(`  ${f.id.padEnd(32)} ${parts.join("   ")}`);
    }
  }

  const worse = cmp.fixtures.filter((f) => f.verdict === "worse").length;
  const better = cmp.fixtures.filter((f) => f.verdict === "better").length;
  console.log(
    `\nSUMMARY  ${better} better, ${worse} worse, ` +
      `${cmp.fixtures.length - better - worse} unchanged, of ${cmp.shared} shared fixtures.`,
  );
  if (cmp.shared < 8) {
    console.log(
      "         Small sample: generation is sampled, so treat single-fixture flips as noise.",
    );
  }
}

/** Re-aggregate over only the fixtures present in BOTH runs, so the numbers compare like with like. */
function aggregateSubset(results, ids) {
  const subset = results.filter((r) => ids.has(r.id));
  const n = subset.length;
  const mean = (fn) => (n ? subset.reduce((a, r) => a + (fn(r) || 0), 0) / n : 0);
  return {
    count: n,
    okRate: n ? subset.filter((r) => r.ok).length / n : 0,
    greenFirstTryRate: n ? subset.filter((r) => r.compiledFirstTry).length / n : 0,
    meanScore: mean((r) => r.score?.score ?? 0),
    meanRepairAttempts: mean((r) => r.repairAttempts),
    meanCredits: mean((r) => r.credits),
    meanWallMs: mean((r) => r.wallMs),
    meanFilesWritten: mean((r) => r.filesWritten),
    totalCredits: subset.reduce((a, r) => a + (r.credits || 0), 0),
  };
}

function checkRows(beforeResults, afterResults, ids) {
  const tally = (results) => {
    const out = {};
    for (const r of results) {
      if (!ids.has(r.id)) continue;
      for (const c of r.score?.checks ?? []) {
        const t = (out[c.id] ??= { pass: 0, applicable: 0 });
        if (c.status === "skip") continue;
        t.applicable++;
        if (c.status === "pass") t.pass++;
      }
    }
    return out;
  };
  const b = tally(beforeResults);
  const a = tally(afterResults);
  return [...new Set([...Object.keys(b), ...Object.keys(a)])].map((id) => ({
    id,
    beforePass: b[id]?.pass ?? 0,
    beforeApplicable: b[id]?.applicable ?? 0,
    afterPass: a[id]?.pass ?? 0,
    afterApplicable: a[id]?.applicable ?? 0,
    delta: (a[id]?.pass ?? 0) - (b[id]?.pass ?? 0),
  }));
}

async function main() {
  let files, opts;
  try {
    ({ files, opts } = parseArgs(process.argv.slice(2)));
  } catch (err) {
    console.error(`${err.message}\n\n${HELP}`);
    process.exit(2);
  }
  if (opts.help || files.length === 0) {
    console.log(HELP);
    process.exit(files.length === 0 && !opts.help ? 2 : 0);
  }

  if (files.length === 1) {
    printSingle(await load(files[0]), opts);
    return;
  }
  if (files.length > 2) {
    console.error("Pass at most two result files.\n\n" + HELP);
    process.exit(2);
  }

  const [before, after] = await Promise.all(files.map(load));
  const bMap = byId(before);
  const aMap = byId(after);
  const sharedIds = new Set([...aMap.keys()].filter((id) => bMap.has(id)));

  const cmp = {
    shared: sharedIds.size,
    onlyBefore: [...bMap.keys()].filter((id) => !aMap.has(id)),
    onlyAfter: [...aMap.keys()].filter((id) => !bMap.has(id)),
    aggBefore: aggregateSubset(before.results, sharedIds),
    aggAfter: aggregateSubset(after.results, sharedIds),
    checks: checkRows(before.results, after.results, sharedIds),
    fixtures: [...sharedIds].map((id) => compareFixture(bMap.get(id), aMap.get(id))),
  };
  cmp.fixtures.sort((x, y) => x.rankDelta - y.rankDelta || x.scoreDelta - y.scoreDelta);

  if (opts.json) {
    console.log(JSON.stringify({ before: before.label, after: after.label, ...cmp }, null, 2));
  } else {
    printComparison(before, after, cmp, opts);
  }

  if (opts.failOnRegression && cmp.fixtures.some((f) => f.verdict === "worse")) {
    process.exit(1);
  }
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});

