import path from "node:path";

const ROOT = "C:/Users/edmem/kodely-prod";
const HERE = import.meta.dirname;
const srcPath = path.join(ROOT, "scripts/eval/results/2026-08-21T17-44-48-482Z-verify.json");
const src = JSON.parse(fs.readFileSync(srcPath, "utf8"));
const clone = (o) => JSON.parse(JSON.stringify(o));

const before = clone(src);
before.label = "synthetic-baseline";
before.git.commit = "0000000";

// plumber: worse in the baseline -> should show as BETTER after
const p = before.results[0];
p.compiledFirstTry = false;
p.repairAttempts = 1;
p.credits = 612;
p.wallMs = 301000;
for (const c of p.score.checks) {
  if (c.id === "meta-description" || c.id === "component-count") { c.status = "fail"; c.detail = "synthetic"; }
}
p.score.passed = 5; p.score.applicable = 7; p.score.score = 5 / 7;

// law-firm: only in the baseline -> should trigger the differing-set note
const gone = clone(src.results[0]); gone.id = "law-firm";
before.results.push(gone);

// saas-landing: green in baseline, broken after -> should show as WORSE
const saasGood = clone(src.results[0]); saasGood.id = "saas-landing";
before.results.push(saasGood);

const after = clone(src);
const saasBad = clone(saasGood);
saasBad.ok = false; saasBad.compiledFirstTry = false; saasBad.repairAttempts = 1;
saasBad.error = "Build failed: TS2304 Cannot find name 'Hero'";
for (const c of saasBad.score.checks) if (c.id !== "html-lang") c.status = "fail";
saasBad.score.passed = 0; saasBad.score.applicable = 7; saasBad.score.score = 0;
after.results.push(saasBad);
after.label = "synthetic-after";

fs.writeFileSync(path.join(HERE, "before.json"), JSON.stringify(before, null, 1));
fs.writeFileSync(path.join(HERE, "after.json"), JSON.stringify(after, null, 1));
console.log("written before.json / after.json");

