import assert from "node:assert/strict";
import { pool, aggregate } from "file:///C:/Users/edmem/kodely-prod/scripts/eval/run.mjs";
import { scoreSite, costMicros, creditsFor } from "file:///C:/Users/edmem/kodely-prod/scripts/eval/score.mjs";

// --- pool: preserves order, respects the concurrency ceiling ---
let inFlight = 0, peak = 0;
const items = Array.from({ length: 9 }, (_, i) => i);
const out = await pool(items, 3, async (x) => {
  inFlight++; peak = Math.max(peak, inFlight);
  await new Promise((r) => setTimeout(r, 5 + (x % 3) * 4));
  inFlight--;
  return x * 2;
});
assert.deepEqual(out, items.map((x) => x * 2), "pool must return results in input order");
assert.equal(peak, 3, `peak concurrency was ${peak}, expected 3`);
console.log("pool: ok (order preserved, peak concurrency 3)");

// --- scoring a FAILED build (dist === null) must degrade, not throw ---
const failed = scoreSite({
  source: { "src/App.tsx": "broken(" },
  dist: null,
  fixture: { id: "x", prompt: "a website", expect: { lang: "es" } },
  foundationPaths: new Set(),
});
assert.equal(failed.score, 0, "a failed build must not score above zero");
assert.equal(failed.applicable, 8, "html-lang is applicable when a language is expected");
console.log("failed build:", JSON.stringify(failed.checks.map((c) => `${c.id}=${c.status}`)));

// --- allowComingSoon inferred from the prompt itself ---
const cs = (prompt, expect) =>
  scoreSite({
    source: { "src/App.tsx": "<h1>Coming soon</h1>", "src/components/A.tsx": "", "src/components/B.tsx": "" },
    dist: { "index.html": '<html lang="en"><title>Verity</title></html>' },
    fixture: { id: "cs", prompt, ...(expect ? { expect } : {}) },
    foundationPaths: new Set(),
  }).checks.find((c) => c.id === "no-placeholder-text").status;
assert.equal(cs("build me a restaurant site"), "fail", "unrequested 'coming soon' must fail");
assert.equal(cs("a coming soon page for Verity"), "pass", "'coming soon' in the prompt must be allowed");
assert.equal(cs("a teaser page", { allowComingSoon: true }), "pass", "expect.allowComingSoon must be honoured");
console.log("coming-soon gating: ok");

// --- outbound <a href> is NOT an external request; <img src> is ---
const ext = (src) =>
  scoreSite({
    source: src,
    dist: { "index.html": "<html></html>" },
    fixture: { id: "e", prompt: "band" },
    foundationPaths: new Set(),
  }).checks.find((c) => c.id === "no-external-requests").status;
assert.equal(ext({ "src/A.tsx": '<a href="https://spotify.com/x">Listen</a>' }), "pass", "outbound link must be fine");
assert.equal(ext({ "src/A.tsx": '<img src="https://cdn.example.com/a.png" />' }), "fail", "remote img must fail");
assert.equal(ext({ "src/index.css": '@import url("https://fonts.googleapis.com/x");' }), "fail", "remote @import must fail");
console.log("external-request discrimination: ok");

// --- cost arithmetic matches lib/credits.ts semantics (micros, not dollars) ---
const rates = { "claude-sonnet-5": { input: 3, output: 15, cacheRead: 0.3, cacheWrite: 3.75 }, default: { input: 5, output: 25, cacheRead: 0.5, cacheWrite: 6.25 } };
const m = costMicros(rates, "claude-sonnet-5", { inputTokens: 1000, outputTokens: 1000, cacheReadTokens: 0, cacheWriteTokens: 0 });
assert.equal(m, 18000, `expected 18000 micros ($0.018), got ${m}`);
assert.equal(creditsFor(m), 9);
assert.equal(costMicros(rates, "who-knows", { inputTokens: 1000, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 }), 5000, "unknown model must fall back to the conservative rate");
console.log("cost arithmetic: ok");

// --- aggregate: a build that never compiled counts against green-first-try ---
const agg = aggregate([
  { ok: true, compiledFirstTry: true, repairAttempts: 0, wallMs: 1000, credits: 10, costMicros: 20000, filesWritten: 5, usage: { outputTokens: 100 }, score: { score: 1, checks: [{ id: "title", status: "pass" }] } },
  { ok: false, compiledFirstTry: false, repairAttempts: 1, wallMs: 2000, credits: 20, costMicros: 40000, filesWritten: 3, usage: { outputTokens: 50 }, score: { score: 0, checks: [{ id: "title", status: "fail" }] } },
]);
assert.equal(agg.greenFirstTryRate, 0.5);
assert.equal(agg.okRate, 0.5);
assert.equal(agg.meanScore, 0.5);
assert.equal(agg.meanScoreOk, 1, "meanScoreOk must average only the builds that compiled");
assert.deepEqual(agg.checkTotals.title, { pass: 1, fail: 1, error: 0, skip: 0 });
console.log("aggregate: ok");

console.log("\nALL UNIT CHECKS PASSED");

